and 1 <= indices.numel() <= 131072,\n43:             \"indices must have shape [N] with N in [1,131072]\")\n44:     require(indices.dtype == torch.uint32, \"uint32 input required\")\n45:     return {\"valid\": True, \"size\": indices.numel()}\n46: \n47: \n48: def run(indices):\n49:     \"\"\"Return unsigned row/column coordinates in a fresh [N,2] tensor.\"\"\"\n50:     validate_inputs(indices)\n51:     n = indices.numel()\n52:     with torch.cuda.device(indices.device):\n53:         output = torch.empty((n, 2), dtype=torch.uint32, device=indices.device)\n54:         _unflatten[(triton.cdiv(n, 256),)](\n55:             indices, output, N=n, BLOCK=256, MULTIPLIER=_MULTIPLIER,\n56:             SHIFT=_SHIFT, num_warps=4)\n57:     return output\n58: \n59: \n60: def reference(indices):\n61:     \"\"\"Exact direct integer division on an int64 widening of each uint32.\"\"\"\n62:     validate_inputs(indices, require_cuda=False)\n63:     values = indices.to(torch.int64)\n64:     rows = torch.div(values, 7, rounding_mode=\"floor\")\n65:     columns = torch.remainder(values, 7)\n66:     return torch.stack((rows, columns), dim=1).to(torch.uint32)\n67: \n68: \n69: def make_inputs(device=\"cuda\", size=4093, seed=0):\n70:     \"\"\"Convenience examples; all uint32 values belong to the input domain.\"\"\"\n71:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n72:     values = torch.randint(0, 1 << 32, (size,), dtype=torch.int64,\n73:                            generator=generator).to(torch.uint32)\n74:     return (values.to(device),)",
